      pa.appendChild(a); pb.appendChild(b); box.appendChild(pa); box.appendChild(pb);
      box.insertAdjacentHTML('beforeend', `<span class="compare-label a">${esc(la)}</span><span class="compare-label b">${esc(lb2)}</span>`);
      const range = el('input', { type: 'range', class: 'compare-range', min: '0', max: '100', step: '1', value: '50', 'aria-label': 'Compare ' + la + ' with ' + lb2 + ': move the divider' });
      const handle = el('div', { class: 'compare-handle', 'aria-hidden': 'true' });
