      tools.innerHTML = '<span class="layer-title">Layers</span>' + names.map(n => `<label class="layer-chip"><input type="checkbox" data-layer="${esc(n)}"> ${esc(n)}</label>`).join('') +
        '<button type="button" data-l="all" title="Show every layer">All</button><button type="button" data-l="none" title="Hide every layer">None</button>';
      (fig.querySelector(':scope > .step-tools') || fig.querySelector(':scope > .svg-viewport') || svg).insertAdjacentElement('afterend', tools);
      const boxes = [...tools.querySelectorAll('input[type="checkbox"]')];
      const apply = () => boxes.forEach(cb => { const on = cb.checked; cb.parentElement.classList.toggle('on', on); byName.get(cb.dataset.layer).forEach(g => g.classList.toggle('layer-hidden', !on)); });
      boxes.forEach(cb => { cb.checked = !byName.get(cb.dataset.layer).some(g => g.dataset.layerOff != null); cb.addEventListener('change', apply); });
      tools.addEventListener('click', e => { const b = e.target.closest('button[data-l]'); if (!b) return; boxes.forEach(cb => { cb.checked = b.dataset.l === 'all'; }); apply(); });
