          const fn = EXPR_FN[name]; next(); const args = [];
          if (peek() && peek().t === ')') next(); else { args.push(expr()); while (peek() && peek().t === ',') { next(); args.push(expr()); } expect(')'); }
          const ar = exprOwn(EXPR_ARITY, name) ? EXPR_ARITY[name] : 1;
          if (ar >= 0 ? args.length !== ar : args.length < 1) throw new Error(name + ' expects ' + (ar >= 0 ? ar : 'at least 1') + ' argument' + (ar === 1 ? '' : 's'));
          if (args.length === 1) { const a = args[0]; return sc => fn(a(sc)); }
