    const labels = String(fig.dataset.labels || '').split(',').map(x => x.trim()).filter(Boolean);
    const trajectories = String(fig.dataset.trajectories || '').split(';').map(t => t.split(',').map(parseFloat)).filter(t => t.length >= 2 && isFinite(t[0]) && isFinite(t[1]));
