      xRange: [xr.a, xr.b], yRange: [yr.a, yr.b], grid: fig.dataset.grid, trajectories, labels, dt: parseFloat(fig.dataset.dt), steps: fig.dataset.steps,
      streamlines: fig.dataset.streamlines, nullclines: fig.dataset.nullclines != null && fig.dataset.nullclines !== 'false', normalize: fig.dataset.normalize !== 'false',
