    const values = (Array.isArray(prm.values) ? prm.values : []).filter(x => isFinite(x)).map(Number).slice(0, 24);
    if (!values.length) return;
    const xr = okPair(cfg.xRange) || [0, 1], N = clampInt(cfg.samples, 2, 2000, 400), perX = cfg.fn.length >= 2;
    const hi = Number.isInteger(cfg.highlight) && cfg.highlight >= 0 && cfg.highlight < values.length ? cfg.highlight : -1;
    const v = cssVar(), c1 = parseColor(v('--s1')) || [37, 99, 235], c6 = parseColor(v('--s6')) || [190, 24, 93];
    const xsv = samplesX(xr[0], xr[1], N, cfg.xScale === 'log');
