  /* ==== BLOCK compute — D1 demo state in the URL hash and presets · D2 export results · D3 unit-aware inputs · D4 uncertainty helpers · D6 sensitivity view (bindControls itself lives in the demo controls section above) ==== */
  const has = (o, k) => Object.prototype.hasOwnProperty.call(o, k);
