  const labelOf = (d, i) => { const l = i.id ? d.querySelector(`label[for="${i.id}"]`) : null; return (l ? l.textContent.trim() : '') || i.id || i.name || 'input'; };

  /* ---- D1 named presets: div.demo-presets > button[data-preset][data-state="k=v&k2=v2"] ---- */
